import{_ as e,o as n,c as s,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"架构决策与技术方案","description":"把架构驱动因素转成系统视图、运行流程、数据与安全设计、ADR、风险实验和可实施技术方案。","frontmatter":{"title":"架构决策与技术方案","description":"把架构驱动因素转成系统视图、运行流程、数据与安全设计、ADR、风险实验和可实施技术方案。","verified_at":"2026-08-01","source":["https://c4model.com/","https://adr.github.io/","https://www.sei.cmu.edu/library/architecture-tradeoff-analysis-method-collection/","https://arc42.org/overview"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/delivery-evolution/architecture-decisions-technical-design.md","filePath":"py-agent/architecture/delivery-evolution/architecture-decisions-technical-design.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/delivery-evolution/architecture-decisions-technical-design.md"};function t(l,a,o,p,h,c){return n(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="架构决策与技术方案" tabindex="-1">架构决策与技术方案 <a class="header-anchor" href="#架构决策与技术方案" aria-label="Permalink to &quot;架构决策与技术方案&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>技术方案不是组件名和云产品的清单。它要解释需求如何映射到边界、数据、运行流程和部署，哪些选择被比较，为什么当前方案值得采用，以及哪些风险必须通过实验才能确认。</p><p>本章关注方案作为交付产物的组织方法。具体模型、框架和存储原理在前文专题中展开。</p><p>开始前应先形成<a href="/py-agent/architecture/system-architecture/requirements-constraints-quality-attributes">需求、约束与质量属性</a>，并用<a href="/py-agent/architecture/system-architecture/system-boundaries-component-responsibilities">系统边界与组件职责</a>确定主要所有权。本章解释怎样把这些输入组织成方案和 ADR，不替代每项技术的实现教程。</p><h2 id="_1-技术方案的职责" tabindex="-1">1. 技术方案的职责 <a class="header-anchor" href="#_1-技术方案的职责" aria-label="Permalink to &quot;1. 技术方案的职责&quot;">​</a></h2><h3 id="_1-1-形成共同模型" tabindex="-1">1.1 形成共同模型 <a class="header-anchor" href="#_1-1-形成共同模型" aria-label="Permalink to &quot;1.1 形成共同模型&quot;">​</a></h3><p>让产品、开发、安全、数据、测试和运维对系统边界、责任和结果流有相同理解。不同读者需要不同视图，而不是一张万能架构图。</p><h3 id="_1-2-支持决策" tabindex="-1">1.2 支持决策 <a class="header-anchor" href="#_1-2-支持决策" aria-label="Permalink to &quot;1.2 支持决策&quot;">​</a></h3><p>把关键约束、候选、权衡和验证证据显式化。方案不应伪装所有问题已经确定。</p><h3 id="_1-3-指导实现" tabindex="-1">1.3 指导实现 <a class="header-anchor" href="#_1-3-指导实现" aria-label="Permalink to &quot;1.3 指导实现&quot;">​</a></h3><p>定义稳定接口、数据所有权、运行不变量、失败语义和里程碑，使团队能拆分工作又不破坏整体约束。</p><h3 id="_1-4-支持验收与演进" tabindex="-1">1.4 支持验收与演进 <a class="header-anchor" href="#_1-4-支持验收与演进" aria-label="Permalink to &quot;1.4 支持验收与演进&quot;">​</a></h3><p>每个架构决策连接到质量属性和测试，系统变化时能判断哪些假设需要复查。</p><h2 id="_2-输入与追踪" tabindex="-1">2. 输入与追踪 <a class="header-anchor" href="#_2-输入与追踪" aria-label="Permalink to &quot;2. 输入与追踪&quot;">​</a></h2><p>技术方案从已确认的项目范围读取：业务结果、用户任务、质量属性场景、硬约束、风险、数据分类和交付阶段。为关键项分配稳定 ID：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REQ-07 退款建议必须引用当前有效政策</span></span>
<span class="line"><span>QA-03  峰值下完整建议 p95 &lt;= 20s</span></span>
<span class="line"><span>SEC-04 未确认不得调用 refund.create</span></span>
<span class="line"><span>ADR-05 使用显式 Workflow 隔离建议与执行</span></span>
<span class="line"><span>TEST-18 退款确认绕过集成测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>追踪关系不必采用复杂工具，但必须能从要求找到决策和验证证据。</p><h2 id="_3-方案视图" tabindex="-1">3. 方案视图 <a class="header-anchor" href="#_3-方案视图" aria-label="Permalink to &quot;3. 方案视图&quot;">​</a></h2><h3 id="_3-1-系统上下文" tabindex="-1">3.1 系统上下文 <a class="header-anchor" href="#_3-1-系统上下文" aria-label="Permalink to &quot;3.1 系统上下文&quot;">​</a></h3><p>展示用户、Agent 系统、身份、模型、业务 API、数据源和运营人员。每条关系标注身份、数据和协议。</p><h3 id="_3-2-容器视图" tabindex="-1">3.2 容器视图 <a class="header-anchor" href="#_3-2-容器视图" aria-label="Permalink to &quot;3.2 容器视图&quot;">​</a></h3><p>展示 API、Worker、Agent/Workflow Runtime、模型网关、数据库、Checkpoint、索引和观测平台等独立运行边界。Container 在此表示部署/运行单元，不等同于 Docker 容器。</p><h3 id="_3-3-组件视图" tabindex="-1">3.3 组件视图 <a class="header-anchor" href="#_3-3-组件视图" aria-label="Permalink to &quot;3.3 组件视图&quot;">​</a></h3><p>展示用例、Agent Runner、Context Builder、Tool Policy、Repository 和外部适配器的责任与依赖。只有能解释责任或变化的组件才进入图。</p><h3 id="_3-4-部署视图" tabindex="-1">3.4 部署视图 <a class="header-anchor" href="#_3-4-部署视图" aria-label="Permalink to &quot;3.4 部署视图&quot;">​</a></h3><p>展示环境、区域、网络边界、身份、资源、副本、数据位置和故障域。开发逻辑图不能替代部署安全和可用性设计。</p><h3 id="_3-5-数据与信任视图" tabindex="-1">3.5 数据与信任视图 <a class="header-anchor" href="#_3-5-数据与信任视图" aria-label="Permalink to &quot;3.5 数据与信任视图&quot;">​</a></h3><p>展示业务数据、Agent State、Checkpoint、记忆、索引、缓存和遥测的权威源、流向、分类与保留；标出所有信任边界。</p><h2 id="_4-关键运行流程" tabindex="-1">4. 关键运行流程 <a class="header-anchor" href="#_4-关键运行流程" aria-label="Permalink to &quot;4. 关键运行流程&quot;">​</a></h2><h3 id="_4-1-正常结果流" tabindex="-1">4.1 正常结果流 <a class="header-anchor" href="#_4-1-正常结果流" aria-label="Permalink to &quot;4.1 正常结果流&quot;">​</a></h3><p>从入口到用户结果绘制 Sequence：认证、任务创建、上下文构建、模型、工具、状态保存、输出和业务终态。每步标注同步/异步与所有者。</p><h3 id="_4-2-人工介入" tabindex="-1">4.2 人工介入 <a class="header-anchor" href="#_4-2-人工介入" aria-label="Permalink to &quot;4.2 人工介入&quot;">​</a></h3><p>展示何处暂停、审批数据如何保存、谁有权恢复、确认如何绑定参数，以及恢复是否重放节点。</p><h3 id="_4-3-故障与恢复" tabindex="-1">4.3 故障与恢复 <a class="header-anchor" href="#_4-3-故障与恢复" aria-label="Permalink to &quot;4.3 故障与恢复&quot;">​</a></h3><p>至少描述模型超时、工具部分成功、队列重复、Checkpoint 恢复、依赖不可用和用户取消。错误路径不是附录，它决定核心状态设计。</p><h3 id="_4-4-版本切换" tabindex="-1">4.4 版本切换 <a class="header-anchor" href="#_4-4-版本切换" aria-label="Permalink to &quot;4.4 版本切换&quot;">​</a></h3><p>展示应用、Prompt、模型、工具 Schema、Workflow 和索引如何组成发布单元，新旧版本如何共存与回滚。</p><h2 id="_5-agent-设计" tabindex="-1">5. Agent 设计 <a class="header-anchor" href="#_5-agent-设计" aria-label="Permalink to &quot;5. Agent 设计&quot;">​</a></h2><h3 id="_5-1-控制结构" tabindex="-1">5.1 控制结构 <a class="header-anchor" href="#_5-1-控制结构" aria-label="Permalink to &quot;5.1 控制结构&quot;">​</a></h3><p>说明为什么使用普通函数、Workflow、单 Agent、Agentic Workflow 或多 Agent。标出模型拥有的决策范围和代码拥有的确定流程。</p><h3 id="_5-2-context" tabindex="-1">5.2 Context <a class="header-anchor" href="#_5-2-context" aria-label="Permalink to &quot;5.2 Context&quot;">​</a></h3><p>定义系统指令、用户输入、记忆、RAG、工具 Schema 的来源、优先级、选择和 Token 预算。不把所有可获得数据默认塞入上下文。</p><h3 id="_5-3-工具" tabindex="-1">5.3 工具 <a class="header-anchor" href="#_5-3-工具" aria-label="Permalink to &quot;5.3 工具&quot;">​</a></h3><p>为每个工具定义参数、返回、身份、授权、副作用、幂等、超时、重试和确认。模型只提出候选动作。</p><h3 id="_5-4-状态与终止" tabindex="-1">5.4 状态与终止 <a class="header-anchor" href="#_5-4-状态与终止" aria-label="Permalink to &quot;5.4 状态与终止&quot;">​</a></h3><p>定义 State Schema、字段所有者、Reducer、Checkpoint 边界、成功/失败/取消/预算耗尽和无进展终止。</p><h3 id="_5-5-输出" tabindex="-1">5.5 输出 <a class="header-anchor" href="#_5-5-输出" aria-label="Permalink to &quot;5.5 输出&quot;">​</a></h3><p>定义结构化结果、引用、流式事件、错误和用户可见状态。框架原始事件通过适配层转换为应用稳定协议。</p><h2 id="_6-数据设计" tabindex="-1">6. 数据设计 <a class="header-anchor" href="#_6-数据设计" aria-label="Permalink to &quot;6. 数据设计&quot;">​</a></h2><h3 id="_6-1-权威源" tabindex="-1">6.1 权威源 <a class="header-anchor" href="#_6-1-权威源" aria-label="Permalink to &quot;6.1 权威源&quot;">​</a></h3><p>业务数据库保存用户承诺，Checkpoint 保存执行位置，Store 保存长期记忆，索引保存派生检索数据，缓存可丢失。技术方案必须明确它们不能互相替代。</p><h3 id="_6-2-schema" tabindex="-1">6.2 Schema <a class="header-anchor" href="#_6-2-schema" aria-label="Permalink to &quot;6.2 Schema&quot;">​</a></h3><p>记录核心实体、ID、租户、状态机、版本、保留和删除。消息和 API 使用版本化 Schema，错误同样是契约。</p><h3 id="_6-3-一致性" tabindex="-1">6.3 一致性 <a class="header-anchor" href="#_6-3-一致性" aria-label="Permalink to &quot;6.3 一致性&quot;">​</a></h3><p>说明事务边界、Outbox、至少一次消息、幂等、并发冲突和最终一致水位。不要写“保证最终一致”而不说明用户可见语义。</p><h3 id="_6-4-容量" tabindex="-1">6.4 容量 <a class="header-anchor" href="#_6-4-容量" aria-label="Permalink to &quot;6.4 容量&quot;">​</a></h3><p>估算文档、Embedding、Checkpoint、Trace、任务和缓存增长，定义分区、归档和重建。</p><h2 id="_7-安全与治理设计" tabindex="-1">7. 安全与治理设计 <a class="header-anchor" href="#_7-安全与治理设计" aria-label="Permalink to &quot;7. 安全与治理设计&quot;">​</a></h2><h3 id="_7-1-身份链" tabindex="-1">7.1 身份链 <a class="header-anchor" href="#_7-1-身份链" aria-label="Permalink to &quot;7.1 身份链&quot;">​</a></h3><p>Principal 如何从入口传播到 Agent、工具、Worker 和数据层，哪些字段可信，如何处理委托 Token。</p><h3 id="_7-2-权限" tabindex="-1">7.2 权限 <a class="header-anchor" href="#_7-2-权限" aria-label="Permalink to &quot;7.2 权限&quot;">​</a></h3><p>按主体、动作、资源和环境授权；租户过滤在数据层强制；高风险动作使用参数绑定确认。</p><h3 id="_7-3-不可信内容" tabindex="-1">7.3 不可信内容 <a class="header-anchor" href="#_7-3-不可信内容" aria-label="Permalink to &quot;7.3 不可信内容&quot;">​</a></h3><p>用户输入、网页、文档、记忆和工具结果均可能 Prompt Injection。说明输入、上下文、动作和输出 Sink 的纵深防护。</p><h3 id="_7-4-数据生命周期" tabindex="-1">7.4 数据生命周期 <a class="header-anchor" href="#_7-4-数据生命周期" aria-label="Permalink to &quot;7.4 数据生命周期&quot;">​</a></h3><p>记录分类、最小化、供应商处理、日志正文、保留、删除和人工访问。Secret 永不进入模型上下文。</p><h3 id="_7-5-sandbox" tabindex="-1">7.5 Sandbox <a class="header-anchor" href="#_7-5-sandbox" aria-label="Permalink to &quot;7.5 Sandbox&quot;">​</a></h3><p>代码、浏览器或文件处理使用何种进程/容器/VM 隔离，网络、文件、资源和凭据如何受限。</p><h2 id="_8-质量与运行设计" tabindex="-1">8. 质量与运行设计 <a class="header-anchor" href="#_8-质量与运行设计" aria-label="Permalink to &quot;8. 质量与运行设计&quot;">​</a></h2><h3 id="_8-1-测试与评测" tabindex="-1">8.1 测试与评测 <a class="header-anchor" href="#_8-1-测试与评测" aria-label="Permalink to &quot;8.1 测试与评测&quot;">​</a></h3><p>把组件/契约/集成测试、任务数据集、指标、Judge/人工、回归门禁映射到具体风险。不是只写“后续补充测试”。</p><h3 id="_8-2-可观测性" tabindex="-1">8.2 可观测性 <a class="header-anchor" href="#_8-2-可观测性" aria-label="Permalink to &quot;8.2 可观测性&quot;">​</a></h3><p>定义 Run/Trace 结构、关键 Span、日志事件、指标、成本归集、采样和敏感内容策略。</p><h3 id="_8-3-性能与成本" tabindex="-1">8.3 性能与成本 <a class="header-anchor" href="#_8-3-性能与成本" aria-label="Permalink to &quot;8.3 性能与成本&quot;">​</a></h3><p>给出关键路径、延迟预算、并发、队列、模型/工具调用预算和每成功任务成本目标。</p><h3 id="_8-4-可靠性" tabindex="-1">8.4 可靠性 <a class="header-anchor" href="#_8-4-可靠性" aria-label="Permalink to &quot;8.4 可靠性&quot;">​</a></h3><p>定义 Deadline、取消、重试所有者、熔断、隔舱、降级、RTO/RPO 和人工运营。</p><h2 id="_9-架构决策记录" tabindex="-1">9. 架构决策记录 <a class="header-anchor" href="#_9-架构决策记录" aria-label="Permalink to &quot;9. 架构决策记录&quot;">​</a></h2><p>ADR 记录一个重要且有后果的决策，而不是整份方案摘要。推荐字段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题与状态</span></span>
<span class="line"><span>背景和驱动约束</span></span>
<span class="line"><span>候选方案</span></span>
<span class="line"><span>决策标准与证据</span></span>
<span class="line"><span>选择</span></span>
<span class="line"><span>正面与负面后果</span></span>
<span class="line"><span>迁移和回滚</span></span>
<span class="line"><span>复查触发器</span></span>
<span class="line"><span>关联需求、实验和负责人</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>状态至少区分 proposed、accepted、superseded、deprecated。新 ADR 取代旧决策时保留历史链，不静默改写过去理由。</p><h2 id="_10-填写后的-adr" tabindex="-1">10. 填写后的 ADR <a class="header-anchor" href="#_10-填写后的-adr" aria-label="Permalink to &quot;10. 填写后的 ADR&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADR-005：退款流程采用 Agentic Workflow</span></span>
<span class="line"><span>状态：accepted</span></span>
<span class="line"><span>背景：政策解释路径开放，但退款创建必须固定审批并可恢复</span></span>
<span class="line"><span>约束：未确认写操作为零；任务可跨进程恢复；团队使用 Python</span></span>
<span class="line"><span>候选：单 Agent；全固定 Workflow；外层 Workflow + 局部建议 Agent</span></span>
<span class="line"><span>选择：第三项</span></span>
<span class="line"><span>依据：同一 300 案例集成功率 96.4%，路径违规 0；单 Agent 有 3 次越过审批提案</span></span>
<span class="line"><span>后果：State 与节点版本需要迁移；建议 Agent 可独立替换；系统复杂度上升</span></span>
<span class="line"><span>回滚：停止新任务进入 v2；进行中 Thread 固定 v1；恢复旧路由</span></span>
<span class="line"><span>复查：写工具增加、任务量增长 10 倍或审批政策变化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>示例数据仅说明记录结构，不是通用技术结论。</p><h2 id="_11-风险实验" tabindex="-1">11. 风险实验 <a class="header-anchor" href="#_11-风险实验" aria-label="Permalink to &quot;11. 风险实验&quot;">​</a></h2><p>对高不确定、高影响、难以回退的假设做 Spike/PoC：模型工具准确性、长上下文、Checkpoint 迁移、目标负载、供应商限流、Sandbox 和跨租户隔离。</p><p>每个实验有假设、环境、样本、测量、通过阈值和结论。PoC 使用代表性失败路径，不能只跑“Hello World”。实验结果进入 ADR，失败同样是有效证据。</p><h2 id="_12-实施切分" tabindex="-1">12. 实施切分 <a class="header-anchor" href="#_12-实施切分" aria-label="Permalink to &quot;12. 实施切分&quot;">​</a></h2><p>按纵向结果流切分里程碑，而不是先完成所有数据库、再完成所有 Agent。每个 Increment 应得到可演示且可测试的用户结果，例如：</p><ol><li>只读政策回答与引用；</li><li>订单工具与结构化建议；</li><li>人工确认与退款任务；</li><li>故障恢复、观测和 Pilot 门禁。</li></ol><p>同时保留跨阶段的 Schema、权限和版本边界，避免原型路径直接成为生产捷径。</p><h2 id="_13-方案评审" tabindex="-1">13. 方案评审 <a class="header-anchor" href="#_13-方案评审" aria-label="Permalink to &quot;13. 方案评审&quot;">​</a></h2><p>评审者按角色查看：业务是否满足任务，工程是否可实现，安全边界是否确定，数据是否合法，测试是否能证明，运维是否能运行，成本是否可接受。</p><p>所有意见标记阻塞、需跟踪或建议；关键未决项有负责人和截止时间。方案批准不代表永久正确，而是当前证据下允许实施。</p><h2 id="_14-常见误区" tabindex="-1">14. 常见误区 <a class="header-anchor" href="#_14-常见误区" aria-label="Permalink to &quot;14. 常见误区&quot;">​</a></h2><ol><li><strong>方案是产品清单</strong>：没有责任、数据流和选择依据。</li><li><strong>只有一张组件图</strong>：运行、数据、安全和部署无法解释。</li><li><strong>框架对象成为业务契约</strong>：升级影响穿透所有层。</li><li><strong>ADR 只记录最终选择</strong>：候选和权衡无法复查。</li><li><strong>风险写“后续关注”</strong>：没有实验、负责人和退出条件。</li></ol><h2 id="_15-交付清单" tabindex="-1">15. 交付清单 <a class="header-anchor" href="#_15-交付清单" aria-label="Permalink to &quot;15. 交付清单&quot;">​</a></h2><ul><li>需求、约束、决策和验证是否可相互追踪；</li><li>系统、容器、组件、部署、数据与信任视图是否各司其职；</li><li>正常、人工、失败、恢复和版本流程是否完整；</li><li>模型、工具、状态和输出边界是否明确；</li><li>业务数据、Checkpoint、记忆、索引和缓存是否区分；</li><li>安全、评测、观测、性能、成本和恢复是否进入设计；</li><li>每个关键决策是否有候选、证据、后果和复查条件；</li><li>高风险假设是否由实验而不是乐观描述证明。</li></ul><p>技术方案的价值不在于预测所有实现细节，而在于让关键约束、边界和决策可见。团队能够据此实现、测试和运维，也能够在假设变化时准确知道该复查哪里。</p>`,100)])])}const b=e(i,[["render",t]]);export{u as __pageData,b as default};
